/// <summary>
/// An offset, a speed change and a rate change, applied together.
/// </summary>
public readonly struct TimeTransform
{
    /// <summary>
    /// How far to shift.
    /// </summary>
    public RationalTime Offset { get; }

    /// <summary>
    /// How much to stretch: 2.0 plays twice as fast.
    /// </summary>
    public double Scale { get; }

    /// <summary>
    /// The rate to resolve to, or a negative number to keep the input's.
    /// </summary>
    public double Rate { get; }

    /// <summary>Makes one from its parts.</summary>
    public TimeTransform(RationalTime offset, double scale, double rate)
    {
        this.Offset = offset;
        this.Scale = scale;
        this.Rate = rate;
    }

    /// <summary>Reads the value back out of the C interface.</summary>
    internal static TimeTransform FromNative(Native.OtioTimeTransform value) =>
        new TimeTransform(RationalTime.FromNative(value.offset), value.scale, value.rate);

    /// <summary>Spells the value the way the C interface wants it.</summary>
    internal Native.OtioTimeTransform ToNative() =>
        new Native.OtioTimeTransform
        {
            offset = this.Offset.ToNative(),
            scale = this.Scale,
            rate = this.Rate,
        };

    /// <summary>What the value holds, for a message or a log.</summary>
    public override string ToString() => $"TimeTransform(Offset={this.Offset}, Scale={this.Scale}, Rate={this.Rate})";

    /// <summary>
    /// Returns the transform applied to a span.
    /// </summary>
    /// <remarks>
    /// <para>
    /// C: <c>otio_time_transform_applied_to_range</c>
    /// </para>
    /// </remarks>
    public TimeRange AppliedToRange(TimeRange range)
    {
        var answer = Native.otio_time_transform_applied_to_range(this.ToNative(), range.ToNative());
        return TimeRange.FromNative(answer);
    }

    /// <summary>
    /// Returns the transform applied to an instant.
    /// </summary>
    /// <remarks>
    /// <para>
    /// C: <c>otio_time_transform_applied_to_time</c>
    /// </para>
    /// </remarks>
    public RationalTime AppliedToTime(RationalTime time)
    {
        var answer = Native.otio_time_transform_applied_to_time(this.ToNative(), time.ToNative());
        return RationalTime.FromNative(answer);
    }

    /// <summary>
    /// Returns the transform applied to another transform.
    /// </summary>
    /// <remarks>
    /// <para>
    /// C: <c>otio_time_transform_applied_to_transform</c>
    /// </para>
    /// </remarks>
    public TimeTransform AppliedToTransform(TimeTransform other)
    {
        var answer = Native.otio_time_transform_applied_to_transform(this.ToNative(), other.ToNative());
        return TimeTransform.FromNative(answer);
    }
}

